<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import DataList from './DataList.vue'
import {Printer,Settings,ArrowUp,ArrowDown,X,Check} from 'lucide-vue-next'
import {api,boot,session,localDate,queue,online} from '../data'
import type {Harvest,Inputs,Rule} from '../types'
type Column='code'|'name'|'groups'|'am'|'pm'|'amWage'|'pmWage'|'total'|'signature'
interface Template {title:string;columns:Column[];fontSize:number;signatureWidth:number}
interface DayWorker {workerId:string;code:string;name:string;records:Harvest[];fingerprint:string;status:'SIGNED'|'UNSIGNED'|'RESIGN';amWage:number;pmWage:number;total:number;valid:boolean;signature?:{signer_name:string;signed_at:string}}
const names:Record<Column,string>={code:'工号',name:'姓名',groups:'各班组采摘量',am:'上午工作量',pm:'下午工作量',amWage:'上午工资（元）',pmWage:'下午工资（元）',total:'当天工资（元）',signature:'工人签字'}
const date=ref(localDate()),group=ref('*'),status=ref('ALL'),workers=ref<DayWorker[]>([]),template=ref<Template>({title:'每日采摘核对表',columns:Object.keys(names) as Column[],fontSize:12,signatureWidth:130})
const dailySearch=ref('')
const snapshots=ref<any[]>([]),comparison=ref<any>(null),frozen=ref<any>(null)
const displayWorkers=computed(()=>printing.value&&frozen.value?frozen.value.workers as DayWorker[]:visible.value)
const displayTemplate=computed(()=>printing.value&&frozen.value?frozen.value.template as Template:template.value)
const settings=ref(false),error=ref(''),message=ref(''),busy=ref(false),loadedDate=ref(''),printing=ref(false)
let generation=0
const pending=computed(()=>queue.value.some(q=>q.operation.workDate===date.value))
const visible=computed(()=>workers.value.filter(w=>(!dailySearch.value.trim()||(w.name+w.code).toLocaleLowerCase().includes(dailySearch.value.trim().toLocaleLowerCase()))&&(status.value==='ALL'||w.status===status.value)&&(group.value==='*'||w.records.some(r=>group.value===''?!r.groups?.length||r.groups.some(g=>g.group_id===''):r.groups?.some(g=>g.group_id===group.value)))))
const isAdmin=computed(()=>session.value?.user.role==='ADMIN')
async function load(){const n=++generation;busy.value=true;error.value='';workers.value=[];loadedDate.value='';try{const result=await api('/daily?date='+date.value);if(n!==generation)return;workers.value=result.workers;template.value=result.template;loadedDate.value=result.date;snapshots.value=await api('/daily/prints?date='+result.date)}catch(e){if(n===generation)error.value=(e as Error).message}finally{if(n===generation)busy.value=false}}
watch(date,load);onMounted(()=>{void load();window.addEventListener('farm-synced',updated);window.addEventListener('afterprint',afterPrint)})
function updated(){void load()}
function afterPrint(){printing.value=false;frozen.value=null}
onBeforeUnmount(()=>{generation++;window.removeEventListener('farm-synced',updated);window.removeEventListener('afterprint',afterPrint)})
function raw(input:Inputs,rule?:Rule){const q=Object.entries(input.quantities||{}).map(([key,n])=>`${rule?.stages.find(s=>s.key===key)?.label||key} ${Number(n)}${rule?.stages.find(s=>s.key===key)?.type==='PIECE'?'筐':input.weightUnit==='jin'?'斤':input.weightUnit==='g'?'克':'公斤'}`);if(input.totalWeight!=null)q.push(`${Number(input.totalWeight)}${input.weightUnit==='jin'?'斤':input.weightUnit==='g'?'克':'公斤'}`);return q.join(' / ')||'0'}
function quantities(w:DayWorker,period:string){return w.records.filter(r=>r.period===period).map(r=>`${r.product_name}：${raw(JSON.parse(r.inputs_json),(r as Harvest&{rule?:Rule}).rule)}`).join('；')||'—'}
function groups(w:DayWorker){return w.records.flatMap(r=>r.groups?.length?r.groups.map(g=>`${r.period==='AM'?'上午':'下午'} ${g.group_name} · ${r.product_name}：${raw(JSON.parse(g.inputs_json),(r as Harvest&{rule?:Rule}).rule)}`):[`${r.period==='AM'?'上午':'下午'} 未分组 · ${r.product_name}：${raw(JSON.parse(r.inputs_json),(r as Harvest&{rule?:Rule}).rule)}`])}
function move(i:number,delta:number){const a=template.value.columns;[a[i],a[i+delta]]=[a[i+delta],a[i]]}
function toggle(c:Column){const a=template.value.columns;template.value.columns=a.includes(c)?a.filter(v=>v!==c):[...a,c]}
async function saveTemplate(){busy.value=true;error.value='';try{template.value=await api('/daily/template',{method:'POST',body:JSON.stringify(template.value)});settings.value=false;message.value='打印模板已保存'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function mark(w:DayWorker){
  if(pending.value){error.value='请先处理当天待同步操作，再核对签字';return}
  if(!confirm(`已收回 ${w.name} 在 ${date.value} 核对表上的纸质签字？签字只确认账目，不代表已付款。`))return
  busy.value=true;error.value='';try{await api('/daily/sign',{method:'POST',body:JSON.stringify({workerId:w.workerId,date:date.value,fingerprint:w.fingerprint})});await load();message.value='已登记纸表签字'}catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
async function print(){
  if(pending.value||!online.value||busy.value)return
  // Re-fetch immediately before printing; never print an old-date or stale snapshot silently.
  await load();if(error.value||loadedDate.value!==date.value||!visible.value.length)return
  try{frozen.value=await api('/daily/prints',{method:'POST',body:JSON.stringify({id:crypto.randomUUID(),date:date.value,groupId:group.value,fingerprints:Object.fromEntries(visible.value.map(w=>[w.workerId,w.fingerprint]))})});printing.value=true;requestAnimationFrame(()=>window.print());snapshots.value=await api('/daily/prints?date='+date.value)}catch(e){error.value=(e as Error).message}
}
async function compare(id:string){error.value='';try{comparison.value=await api('/daily/prints/'+id)}catch(e){error.value=(e as Error).message}}
function changeText(log:any){const names:Record<string,string>={CREATE:'新增采摘记录',UPDATE:'修改采摘记录',ADD_QUANTITY:'增加采摘量',CORRECT_QUANTITY:'更正数量',MOVE_PLOT:'更正地块',DELETE:'删除未结算记录',RESTORE:'恢复记录',PUBLISH_RULE:'发布计费规则'};return log.reason||JSON.parse(log.after_json||'null')?.note||names[log.action]||'资料变更'}
function oldAmount(w:any){return Number(w.total).toFixed(2)}
function dayDetails(w:any){return w?w.records.map((r:Harvest)=>r.product_name+' '+(r.period==='AM'?'上午':'下午')+' '+raw(JSON.parse(r.inputs_json),r.rule)).join('；'):'无有效记录'}
function plotDetails(w:any){return w?w.records.flatMap((r:Harvest)=>(r.allocations||[]).map(a=>a.group_name+' / '+a.plot_name+' '+raw(JSON.parse(a.inputs_json),r.rule))).join('；'):'—'}
function currentWorker(id:string){return comparison.value?.current.workers.find((w:any)=>w.workerId===id)}
const statusName=(s:string)=>s==='SIGNED'?'已签字':s==='RESIGN'?'需重新签字':'未签字'
</script>
<template><div class="page-intro no-print"><div><p class="eyebrow">当天核对，纸表签字</p><h1>每日核对</h1><p class="muted">同一工人的跨组工作放在一起，工资只列一次。</p></div><div class="button-row"><button v-if="isAdmin" @click="settings=true"><Settings :size="17"/>打印设置</button><button class="primary" :disabled="busy||pending||!online||!visible.length" @click="print"><Printer :size="17"/>打印核对表</button></div></div>
  <div class="ledger-toolbar no-print"><label>工人姓名 / 工号<input v-model="dailySearch" aria-label="核对查询" placeholder="查询工人姓名或工号"/></label><label>核对日期<input v-model="date" type="date" :max="localDate()" required/></label><label>班组<select aria-label="班组" v-model="group"><option value="*">全部班组</option><option value="">未分组</option><option v-for="g in boot?.groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>签字状态<select aria-label="签字状态" v-model="status"><option value="ALL">全部状态</option><option value="UNSIGNED">未签字</option><option value="SIGNED">已签字</option><option value="RESIGN">需重新签字</option></select></label><button :disabled="busy" @click="load">刷新核对表</button></div>
  <p class="notice no-print">签字表示工作量及工资核对无误，不代表已付款。筛选班组后仍显示所选工人的完整当天账目，每人一行、签一次。记录员也可核对往日完整账目；仅改地块且总量、工资不变时无需重新签字。</p>
  <p v-if="pending" class="notice danger no-print">当天有待处理的本机操作，请先同步并核对，再打印或登记签字。</p><p v-if="!online" class="notice no-print">每日核对、打印和签字登记需要联网读取最新账目。</p>
  <p v-if="error" class="notice danger no-print" role="alert">{{error}}</p><p v-if="message" class="notice success no-print" role="status">{{message}}</p>
  <DataList endpoint="/query/daily" :params="{date,status,groupId:group,q:dailySearch}" :rows="visible" :show-search="false" :refresh-key="workers" scope="每日核对" v-slot="{items}"><section class="daily-print-area" :style="{'font-size':displayTemplate.fontSize+'px'}"><h2>{{displayTemplate.title}}</h2><p>{{loadedDate||date}} · {{displayWorkers.length}} 人 · {{group==='*'?'全部班组':group===''?'未分组':boot?.groups?.find(g=>g.id===group)?.name}}<span v-if="status!=='ALL'"> · {{statusName(status)}}</span></p>
    <div class="panel table-wrap daily-table"><table><thead><tr><th v-for="c in displayTemplate.columns" :key="c" :style="c==='signature'?{'width':displayTemplate.signatureWidth+'px','min-width':displayTemplate.signatureWidth+'px'}:{}">{{names[c]}}</th><th class="no-print">核对状态 / 操作</th></tr></thead><tbody><tr v-for="w in (printing&&frozen?displayWorkers:items)" :key="w.workerId"><td v-for="c in displayTemplate.columns" :key="c"><template v-if="c==='code'">{{w.code}}</template><strong v-else-if="c==='name'">{{w.name}}</strong><template v-else-if="c==='groups'"><div v-for="(line,i) in groups(w)" :key="i" class="group-line">{{line}}</div></template><template v-else-if="c==='am'||c==='pm'">{{quantities(w,c==='am'?'AM':'PM')}}</template><template v-else-if="c==='signature'"><span class="signature-space"></span></template><template v-else>{{w.valid?Number(w[c]).toFixed(2):'待核对'}}</template></td><td class="no-print"><span class="tag" :class="w.status==='SIGNED'?'good':w.status==='RESIGN'?'error':'neutral'">{{statusName(w.status)}}</span><small v-if="w.signature">{{w.signature.signer_name}} · {{w.signature.signed_at}}</small><button v-if="w.status!=='SIGNED'" class="compact" :disabled="busy||pending||!online||!w.valid" @click="mark(w)"><Check :size="14"/>登记已签字</button></td></tr></tbody></table><div v-if="!visible.length" class="empty">{{busy?'正在读取当天账目…':'没有符合条件的完整核对记录。'}}</div></div>
    <p v-if="printing&&frozen" class="print-footnote">打印版本 {{frozen.id}} · {{frozen.generatedAt}} · {{frozen.generatedBy}}</p><p class="print-footnote">签字仅确认采摘数量和工资，不表示已收到工资。数量或工资更正后，请重新打印、核对签字，并保留原纸表。</p>
  </section></DataList>
  <section class="panel no-print"><h3>历史打印快照</h3><p class="muted">保留生成时的原样，仅供查看和对比，不提供旧版重打。取消打印也会保留版本。</p><DataList endpoint="/query/prints" :params="{date}" :rows="snapshots" :refresh-key="snapshots" scope="历史打印快照" v-slot="{items}"><div v-for="s in items" :key="s.id" class="list-row"><span>{{s.created_at}} · {{s.creator_name}}<small>{{s.id}}</small></span><button @click="compare(s.id)">查看旧版与当前差异</button></div></DataList><p v-if="!snapshots.length" class="muted">当天没有打印存档。</p></section>
  <div v-if="comparison" class="modal-shade no-print" @click.self="comparison=null"><section class="modal wide-modal" role="dialog" aria-modal="true" aria-label="历史打印快照"><div class="modal-head"><h2>旧打印版本与当前账目</h2><button @click="comparison=null">关闭</button></div><p>{{comparison.snapshot.template.title}} · {{comparison.snapshot.date}} · {{comparison.snapshot.generatedAt}} · {{comparison.snapshot.generatedBy}}</p><p class="notice">旧表保持生成时的原样。当前数据仅用于对比；打印请返回当前每日核对表。</p><DataList :rows="comparison.snapshot.workers" scope="打印差异" v-slot="{items}"><div class="table-wrap"><table><thead><tr><th>工人</th><th>旧版工作量 / 地块</th><th>当前工作量 / 地块</th><th>旧版工资 → 当前工资</th></tr></thead><tbody><tr v-for="w in items" :key="w.workerId"><td>{{w.name}}<small>{{w.code}}</small></td><td class="wrap-cell">{{dayDetails(w)}}<small>{{plotDetails(w)}}</small></td><td class="wrap-cell">{{dayDetails(currentWorker(w.workerId))}}<small>{{plotDetails(currentWorker(w.workerId))}}</small></td><td>{{oldAmount(w)}} → {{currentWorker(w.workerId)?oldAmount(currentWorker(w.workerId)):'0.00'}}</td></tr></tbody></table></div></DataList><h3>生成时的原表</h3><section class="snapshot-original" :style="{'font-size':comparison.snapshot.template.fontSize+'px'}"><h2>{{comparison.snapshot.template.title}}</h2><p>{{comparison.snapshot.date}} · {{comparison.snapshot.generatedAt}}</p><DataList :rows="comparison.snapshot.workers" scope="原打印表" v-slot="{items}"><div class="table-wrap"><table><thead><tr><th v-for="c in comparison.snapshot.template.columns" :key="c" :style="c==='signature'?{width:comparison.snapshot.template.signatureWidth+'px'}:{}">{{names[c as Column]}}</th></tr></thead><tbody><tr v-for="w in items" :key="w.workerId"><td v-for="c in comparison.snapshot.template.columns" :key="c"><template v-if="c==='code'">{{w.code}}</template><template v-else-if="c==='name'">{{w.name}}</template><template v-else-if="c==='groups'"><div v-for="(line,i) in groups(w)" :key="i">{{line}}</div></template><template v-else-if="c==='am'||c==='pm'">{{quantities(w,c==='am'?'AM':'PM')}}</template><span v-else-if="c==='signature'" class="signature-space"></span><template v-else>{{w.valid?Number(w[c]).toFixed(2):'待核对'}}</template></td></tr></tbody></table></div></DataList></section><h3>相关修改经过</h3><DataList :rows="comparison.changes" scope="打印相关修改" v-slot="{items}"><div v-for="l in items" :key="l.id" class="history-item"><strong>{{l.actor_name}} · {{l.created_at}}</strong><p>{{changeText(l)}}</p></div></DataList><p v-if="!comparison.changes.length" class="muted">没有后续相关修改记录。</p></section></div>
  <div v-if="settings" class="modal-shade no-print" @click.self="settings=false"><section class="modal" role="dialog" aria-modal="true" aria-label="打印设置"><div class="modal-head"><h2>打印设置</h2><button class="icon-button" aria-label="关闭" @click="settings=false"><X/></button></div><form @submit.prevent="saveTemplate"><label>表格标题 / 农场名称<input v-model="template.title" maxlength="80" required/></label><div class="form-grid"><label>字号<input v-model.number="template.fontSize" type="number" min="9" max="24" required/></label><label>签字栏宽度<input v-model.number="template.signatureWidth" type="number" min="80" max="300" required/></label></div><p class="muted">姓名和签字栏始终保留，其余栏目可选。</p><label v-for="(name,key) in names" :key="key" class="check-label"><input type="checkbox" :checked="template.columns.includes(key)" :disabled="key==='name'||key==='signature'" @change="toggle(key)"/>{{name}}</label><h3>已选栏目顺序</h3><div v-for="(c,i) in template.columns" :key="c" class="list-row"><span>{{names[c]}}</span><div class="button-row"><button type="button" class="icon-button" :disabled="i===0" :aria-label="'上移'+names[c]" @click="move(i,-1)"><ArrowUp :size="16"/></button><button type="button" class="icon-button" :disabled="i===template.columns.length-1" :aria-label="'下移'+names[c]" @click="move(i,1)"><ArrowDown :size="16"/></button></div></div><p v-if="error" class="notice danger">{{error}}</p><div class="modal-actions"><button class="primary" :disabled="busy">保存打印设置</button></div></form></section></div>
</template>
